// One-hot state encoding: 000001, 000010, 000100, 001000, 010000, 100000
// Transition diagram:
//
//  A (0) --0--> B
//  A (0) --1--> A
//  B (0) --0--> C
//  B (0) --1--> D
//  C (0) --0--> E
//  C (0) --1--> D
//  D (0) --0--> F
//  D (0) --1--> A
//  E (1) --0--> E
//  E (1) --1--> D
//  F (1) --0--> C
//  F (1) --1--> D
//
// Derive the next-state signals Y2 and Y4 corresponding to signals y[1]
// and y[3].
module TopModule(
    input [5:0] y,
    input w,
    output reg Y1,
    output reg Y3
);
    reg [5:0] state = {1'b0, 1'b0, 1'b0, 1'b0, 1'b0, 1'b1};
    reg [5:0] next_state;
    wire Y2 = state[1];
    wire Y4 = state[3];
    always @* begin
        case(state)
            6'b000001: next_state = 6'b000010;
            6'b000010: next_state = w ? 6'b000100 : 6'b000001;
            6'b000100: next_state = Y2 ? 6'b001000 : 6'b000010;
            6'b001000: next_state = Y2 ? 6'b010000 : 6'b000100;
            6'b010000: next_state = Y2 ? (Y4 ? 6'b100000 : 6'b001000) : 6'b000100;
            6'b100000: next_state = Y2 ? (Y4 ? 6'b000001 : 6'b010000) : 6'b000100;
            default: next_state = 6'b000001;
        endcase
    end
    always @(posedge y[0]) state <= next_state;
    always @* Y1 = state[0];
    always @* Y3 = state[2];
endmodule

