// One-hot state machine, next-state signals explicitly named.
module TopModule(
    input  [5:0] y,
    input  w,
    output reg Y1,
    output reg Y3
);
    reg [5:0] ns;
    reg [5:0] y_reg;
    wire Y2 = y_reg[1];
    wire Y4 = y_reg[3];
    always @(*) begin
        case (y_reg)
            // Next state function for each state, explicitly named.
            // (The register name is the state name + _ns)
            6'b000001: ns = Y2 ? 6'b000010 : 6'b000001;
            6'b000010: ns = Y2 ? 6'b000100 : 6'b000001;
            6'b000100: ns = Y2 ? 6'b001000 : 6'b000010;
            6'b001000: ns = Y2 ? 6'b010000 : 6'b000100;
            6'b010000: ns = Y2 ? 6'b100000 : (Y4 ? 6'b000010 : 6'b000001);
            6'b100000: ns = Y2 ? 6'b000001 : (Y4 ? 6'b000010 : 6'b000001);
            default: ns = 6'b000001;
        endcase
    end
    always @(posedge w) begin
        y_reg <= ns;
        Y1 <= y_reg[1];
        Y3 <= y_reg[3];
    end
endmodule

